mkdir -p test && cat > test/order-total.test.mjs <<'EOF'
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 101, E: 100.01 }
let server, base

before(async () => {
  server = createServer(createApp({ pricing: { priceOf: async (sku) => prices[sku] } }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const totalFor = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// These pin CURRENT behaviour (characterization) so refactors that change totals are noticed.
test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 70)
})

test('no discount at exactly 100 (threshold is strictly greater than)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount above 100', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 10 }]), 225)
})

test('discounted total is truncated, not rounded (101 -> 90.9 -> 90)', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 90)
})

test('100.01 is discounted to 90.009 -> 90', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)
})

test('undiscounted fractional totals are truncated (99.99 -> 99)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 99)
})

test('discount applies to whole order, not per item', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 6 }, { sku: 'B', qty: 2 }]), 99)
})
EOF
npm test 2>&1 | tail -15

